def verify_wheel_notice(wheel_path: Path, notice: str) -> None:
    """Keep the root notice in wheel metadata without standalone copies."""

    notice_bytes = notice.encode("utf-8")
    start_marker = NOTICE_START.encode("utf-8")
    end_marker = NOTICE_END.encode("utf-8")
    normalized_notice = notice_bytes.replace(b"\r\n", b"\n")
    with ZipFile(wheel_path) as archive:
        metadata_names = [
            name
            for name in archive.namelist()
            if name.endswith(".dist-info/METADATA")
        ]
        if len(metadata_names) != 1:
            raise ThirdPartyNoticeError(
                "wheel 必须恰好包含一份可核验第三方声明的 METADATA"
            )
        try:
            metadata = archive.read(metadata_names[0])
            metadata.decode("utf-8")
        except (KeyError, UnicodeDecodeError) as error:
            raise ThirdPartyNoticeError(
                "wheel 元数据缺少可解析第三方声明"
            ) from error
        duplicate_paths = [
            entry.filename
            for entry in archive.infolist()
            if not entry.is_dir()
            and entry.filename != metadata_names[0]
            and normalized_notice in archive.read(entry).replace(b"\r\n", b"\n")
        ]
        if duplicate_paths:
            raise ThirdPartyNoticeError(
                "wheel 不得包含独立第三方声明副本：" + "、".join(duplicate_paths)
            )
    normalized_metadata = metadata.replace(b"\r\n", b"\n")
    if (
        metadata.count(start_marker) != 1
        or metadata.count(end_marker) != 1
        or normalized_notice not in normalized_metadata
    ):
        raise ThirdPartyNoticeError("wheel 长描述没有机械携带唯一根 README 声明")
    parsed_metadata = BytesParser(policy=policy.default).parsebytes(metadata)
    license_headers = parsed_metadata.get_all("License-File", [])
    if license_headers:
        raise ThirdPartyNoticeError(
            "wheel 不得登记独立许可文件；第三方声明只随根 README 进入长描述"
        )

def project_direction_context(
    product_definition: Mapping[str, Any],
    *,
    observed_commit: str | None,
) -> dict[str, Any]:
    """Project all current product choices without selecting what is relevant.

    The digest is only an internal freshness binding. It is computed over the
    complete projected product purpose, capability catalog and guardrail text;
    it neither classifies those values nor proves their meaning.
    """

    revision = product_definition.get("revision")
    revision = revision if isinstance(revision, Mapping) else {}
    stages = list(product_definition.get("delivery_stages") or [])
    current_stages = [
        stage
        for stage in stages
        if isinstance(stage, Mapping)
        and stage.get("commitment") == "current_target"
    ]
    if revision.get("status") != "confirmed" or len(current_stages) != 1:
        raise ProjectProductDefinitionError(
            ["方向决定上下文只能从已确认且具有唯一当前阶段的产品定义投影"]
        )

    product = {
        "product_id": str(product_definition.get("product_id") or ""),
        "revision_id": str(revision.get("revision_id") or ""),
        "title": str(product_definition.get("title") or ""),
        "purpose": str(product_definition.get("purpose") or ""),
        "current_stage": {
            "stage_id": str(current_stages[0].get("stage_id") or ""),
            "title": str(current_stages[0].get("title") or ""),
            "description": str(current_stages[0].get("description") or ""),
        },
    }
    capabilities = [
        {
            "capability_ref": "product.capability:"
            + str(capability.get("capability_id") or ""),
            "capability_id": str(capability.get("capability_id") or ""),
            "title": str(capability.get("title") or ""),
            "description": str(capability.get("description") or ""),
        }
        for capability in product_definition.get("capabilities") or []
        if isinstance(capability, Mapping)
    ]
    guardrails = [
        {
            "decision_ref": "product.non_goal:"
            + str(item.get("non_goal_id") or ""),
            "kind": "non_goal",
            "stable_id": str(item.get("non_goal_id") or ""),
            "statement": str(item.get("statement") or ""),
        }
        for item in product_definition.get("non_goals") or []
        if isinstance(item, Mapping)
    ] + [
        {
            "decision_ref": "product.constraint:"
            + str(item.get("constraint_id") or ""),
            "kind": "constraint",
            "stable_id": str(item.get("constraint_id") or ""),
            "statement": str(item.get("statement") or ""),
        }
        for item in product_definition.get("constraints") or []
        if isinstance(item, Mapping)
    ]
    content = {
        "product": product,
        "capability_catalog": capabilities,
        "guardrails": guardrails,
    }
    digest = hashlib.sha256(
        json.dumps(
            content,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        ).encode("utf-8")
    ).hexdigest()
    return {
        "schema_version": PROJECT_DIRECTION_CONTEXT_SCHEMA,
        "authority_scope": "adopted_integration_commit",
        "observed_commit": observed_commit,
        "context_ref": (
            "product-definition:"
            + product["product_id"]
            + ":"
            + product["revision_id"]
            + ":sha256:"
            + digest
        ),
        **content,
        "semantic_relevance_machine_proven": False,
    }

@staticmethod
def _acyclic(
    module_ids: set[str],
    edges: set[tuple[str, str]],
) -> bool:
    graph: dict[str, set[str]] = defaultdict(set)
    indegree = {identifier: 0 for identifier in module_ids}
    for start, end in edges:
        if end not in graph[start]:
            graph[start].add(end)
            indegree[end] += 1
    queue = deque(sorted(key for key, value in indegree.items() if value == 0))
    visited = 0
    while queue:
        identifier = queue.popleft()
        visited += 1
        for target in sorted(graph[identifier]):
            indegree[target] -= 1
            if indegree[target] == 0:
                queue.append(target)
    return visited == len(module_ids)

